# DK TBP.  Tørsbøl - Padborg
#
let tp = path("d3.dk.tbp");

with detail = 3, railway = :first :pax :removed {
    # point.dk.Tørsbøl  dk.SBT

    with link = "line.dk.TBP" {
        track(:ror,
                tp[:tor.yp - 0.1dl, :tor.yp] << 1ms << 1mt
            ..  tp[:tor.xp + 2mt, :tor.xp + 2.1mt]
        );
        track(tp[:tor.xp + 2mt, :tor.xp + 1.51km]);
        line_label(:right:se, tp[:tor.xp + 1.5km] >> 0.5mt, "TBP");
        track(tp[:tor.xp + 1.49km, :hol - 0.49sw]);
    }

    with link = "point.dk.Holbøl", railway = :station {
        track(tp[:hol - 0.5sw, :hol + 0.5sw]);
        marker(:left :de.bf, tp[:hol] << 0.5mt);
        slabel(:bottom, tp[:hol] << 0.5mt << 1sh << 0.3dt,
            "Holbøl"
        );
    }

    with link = "line.dk.TBP" {
        track(tp[:hol + 0.49sw, :sme - 0.49sw]);
    }

    with link = "point.dk.Smedeby", railway = :station {
        track(tp[:sme - 0.5sw, :sme + 0.5sw]);
        marker(:left :de.bf, tp[:sme] << 0.5mt);
        slabel(:right, tp[:sme] << 0.5mt << 1sh + (1.2dt, 1.1dt),
            "Smedeby"
        );
    }

    with link = "line.dk.TBP" {
        track(tp[:sme + 0.49sw, :sme + 1.21km]);
        line_label(:left:w, tp[:sme + 1.2km] << 0.5mt, (0dt, 0.3dt), "TBP");
        track(tp[:sme + 1.19km, :pad.xt]);
        track(:ror,
                tp[:pad.xt - 0.1dl, :pad.xt]
            ..  tp[:pad.yt, :pad.yt + 0.1dl] << 0.5md >> 0.5mt
        );
    }
}

